From 6043c7daf0185faf15f34556efe7aa993cddb241 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 10:16:07 +0100
Subject: [PATCH] window: don't resize applet popups away from their panel with
 Meta+RMB

Meta+right-drag picked the edges to resize from the pointer position
only, so an applet popup could be pulled over its panel or away from the
screen edge it sits against. Those edges are now left out for popups.

BUG: 507821
---
 src/window.cpp | 82 +++++++++++++++++++++++++++++++++++++++++++++-----
 1 file changed, 75 insertions(+), 7 deletions(-)

diff --git a/src/window.cpp b/src/window.cpp
index 214e2d7671..f232067b30 100644
--- a/src/window.cpp
+++ b/src/window.cpp
@@ -2045,6 +2045,60 @@ bool Window::mousePressCommandConsumesEvent(Options::MouseCommand command) const
     return false;
 }

+/**
+ * Returns the edges of an applet popup that face its panel or touch the screen edge. The popup
+ * is placed against them, so it must not be resized from those edges.
+ */
+static Qt::Edges appletPopupAttachedEdges(const Window *popup)
+{
+    Qt::Edges edges;
+    const RectF geometry = popup->frameGeometry();
+
+    // applet popups have no transient parent, take the nearest panel as theirs
+    const Window *panel = nullptr;
+    qreal panelDistance = 0;
+    for (const Window *window : workspace()->windows()) {
+        if (!window->isDock() || window->output() != popup->output()) {
+            continue;
+        }
+        const RectF panelGeometry = window->frameGeometry();
+        const qreal distance = std::max({panelGeometry.left() - geometry.right(),
+                                         geometry.left() - panelGeometry.right(),
+                                         panelGeometry.top() - geometry.bottom(),
+                                         geometry.top() - panelGeometry.bottom()});
+        if (!panel || distance < panelDistance) {
+            panel = window;
+            panelDistance = distance;
+        }
+    }
+    if (panel) {
+        const RectF panelGeometry = panel->frameGeometry();
+        const qreal dx = (geometry.center().x() - panelGeometry.center().x()) / panelGeometry.width();
+        const qreal dy = (geometry.center().y() - panelGeometry.center().y()) / panelGeometry.height();
+        if (std::abs(dy) > std::abs(dx)) {
+            edges |= dy < 0 ? Qt::BottomEdge : Qt::TopEdge;
+        } else {
+            edges |= dx < 0 ? Qt::RightEdge : Qt::LeftEdge;
+        }
+    }
+
+    const RectF screenArea = workspace()->clientArea(ScreenArea, popup, geometry.center());
+    if (geometry.left() <= screenArea.left()) {
+        edges |= Qt::LeftEdge;
+    }
+    if (geometry.right() >= screenArea.right()) {
+        edges |= Qt::RightEdge;
+    }
+    if (geometry.top() <= screenArea.top()) {
+        edges |= Qt::TopEdge;
+    }
+    if (geometry.bottom() >= screenArea.bottom()) {
+        edges |= Qt::BottomEdge;
+    }
+
+    return edges;
+}
+
 bool Window::performMousePressCommand(Options::MouseCommand cmd, const QPointF &globalPos)
 {
     // NOTE that this has to be checked before running the command
@@ -2188,26 +2242,40 @@ bool Window::performMousePressCommand(Options::MouseCommand cmd, const QPointF &
         if (!isResizable()) {
             break;
         }
+        const QPointF moveOffset = QPointF(globalPos.x() - x(), globalPos.y() - y()); // map from global
+        int x = moveOffset.x(), y = moveOffset.y();
+        bool left = x < width() / 3;
+        bool right = x >= 2 * width() / 3;
+        bool top = y < height() / 3;
+        bool bot = y >= 2 * height() / 3;
+        if (!top && !bot) {
+            left = x < width() / 2;
+            right = !left;
+        }
+        if (isAppletPopup()) {
+            const Qt::Edges attachedEdges = appletPopupAttachedEdges(this);
+            left = left && !attachedEdges.testFlag(Qt::LeftEdge);
+            right = right && !attachedEdges.testFlag(Qt::RightEdge);
+            top = top && !attachedEdges.testFlag(Qt::TopEdge);
+            bot = bot && !attachedEdges.testFlag(Qt::BottomEdge);
+            if (!left && !right && !top && !bot) {
+                break;
+            }
+        }
         if (isInteractiveMoveResize()) {
             finishInteractiveMoveResize(false);
         }
         setInteractiveMoveResizePointerButtonDown(true);
         setInteractiveMoveResizeAnchor(globalPos);
         setInteractiveMoveResizeModifiers(Qt::KeyboardModifiers());
-        const QPointF moveOffset = QPointF(globalPos.x() - x(), globalPos.y() - y()); // map from global
         setInteractiveMoveOffset(QPointF(moveOffset.x() / width(), moveOffset.y() / height()));
-        int x = moveOffset.x(), y = moveOffset.y();
-        bool left = x < width() / 3;
-        bool right = x >= 2 * width() / 3;
-        bool top = y < height() / 3;
-        bool bot = y >= 2 * height() / 3;
         Gravity gravity;
         if (top) {
             gravity = left ? Gravity::TopLeft : (right ? Gravity::TopRight : Gravity::Top);
         } else if (bot) {
             gravity = left ? Gravity::BottomLeft : (right ? Gravity::BottomRight : Gravity::Bottom);
         } else {
-            gravity = (x < width() / 2) ? Gravity::Left : Gravity::Right;
+            gravity = left ? Gravity::Left : Gravity::Right;
         }
         setInteractiveMoveResizeGravity(gravity);
         setUnrestrictedInteractiveMoveResize((cmd == Options::MouseUnrestrictedResize));
